css:
.loader {
  position: relative;
  width: 46px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 8px;
  height: 6px;
  margin-left: -4px;
  border-radius: 2px 2px 0 0;
  background: #4338ca;
}
.loader::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 44px;
  height: 44px;
  margin-left: -22px;
  border-radius: 50%;
  border: 3px solid #6366f1;
  box-sizing: border-box;
}
.loader i {
  position: absolute;
  left: 50%;
  bottom: 22px;
  width: 2px;
  height: 18px;
  margin-left: -1px;
  border-radius: 2px;
  background: #6366f1;
  transform-origin: bottom center;
  animation: spin 1.2s linear infinite;
}
.loader i::after {
  content: "";
  position: absolute;
  bottom: -3px;
  left: 50%;
  width: 6px;
  height: 6px;
  margin-left: -3px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes spin { to { transform: rotate(360deg); } }
